"""
Module for detecting and managing sleeping cells in BTS systems.

This module provides the sleeping_cell_detector class, which is designed to
detect sleeping cells during tests by monitoring alarms and configuring
RACH-based sleeping cell detection features for both 5G (NR) and LTE cells.

:copyright: Nokia Networks
:author: Damian Silkowski, Mateusz Potoniec
:maintainer: Damian Silkowski, Mateusz Potoniec
:contact: damian.silkowski@nokia.com, mateusz.potoniec@nokia.com
"""

import logging
from typing import List, Dict, Any, Callable, Optional

from taf.ul.alarms_watchdog import alarms_watchdog, Alarm
from taf.ul.alarms_watchdog.exceptions import DisallowedAlarmsDetected, WatchdogNotStarted
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GnbLog, EnbLog
from taf.rfrl.bts.devices.du.commissioning import GnbCommissioning, EnbCommissioning
from taf.rfrl.bts.devices.du.du_operations import GnbDuOperations, EnbDuOperations
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.logger import custom_logger as logger
from taf.internal.sbts.admin.cli.exception import AdminApiProcedureFailureException


class sleeping_cell_detector(object):
    SLEEPING_CELL_ALARM_ID = '7114'
    SLEEPING_CELL_FAULT_ID = '4547'
    SLEEPING_CELL_FAULT_NAME = 'Sleeping Cell Detection Due To Degraded RACH Setup Attempts'
    SLEEPING_CELL_ALARM = Alarm(alarm_id=SLEEPING_CELL_ALARM_ID,
                                fault_id=SLEEPING_CELL_FAULT_ID,
                                fault_name=SLEEPING_CELL_FAULT_NAME)

    def __init__(self, bts_type: str = 'GNB') -> None:
        """
        Library helps to detect a sleeping cell during tests.
        :param bts_type (str): type of bts: GNB or ENB; default GNB
        """
        self.watchdogs: List[Dict[str, Any]] = []
        self.__initialise_bts_objects(bts_type=bts_type)
        self.tl = get_builtin_value(param_name="tl")

    def __initialise_bts_objects(self, bts_type: str) -> None:
        """
        Initialize BTS-specific objects based on the BTS type.
        :param bts_type (str): Type of BTS (GNB or ENB)
        :raises ValueError: If bts_type is not GNB or ENB
        """
        if bts_type == "GNB":
            self.log = GnbLog()
            self.commissioning = GnbCommissioning()
            self.du = GnbDuOperations()
        elif bts_type == "ENB":
            self.log = EnbLog()
            self.commissioning = EnbCommissioning()
            self.du = EnbDuOperations()
        else:
            raise ValueError(f"Wrong bts type: {bts_type}")

    @load_moler_configuration_from_tl()
    def start_sleeping_cell_detection_watchdog(self, log_dir: Optional[str] = None, bts_id: int = 0, du_id: int = 0) -> None:
        """
        Enable sleeping cell detection watchdog for specified BTS and DU.
        :param log_dir (Optional[str]): Directory for storing logs and snapshots
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        bts_config = self.tl.gnbs[int(bts_id)]
        watchdog = alarms_watchdog()
        watchdog.run_when_alarm_detected(trigger_alarms=[self.SLEEPING_CELL_ALARM],
                                         callback=self.log.collect_snapshot,
                                         log_dir=log_dir)
        watchdog.watch_alarms(bts_config=bts_config, log_dir=log_dir, du_id=du_id)
        self.watchdogs.append({
            'bts_id': bts_id,
            'du_id': du_id,
            'watchdog': watchdog
        })

    def verify_sleeping_cell_detection(self) -> None:
        """
        Verify if sleeping cell alarm was detected by any active watchdog.
        :raises WatchdogNotStarted: If watchdog was not started for a BTS/DU
        :raises DisallowedAlarmsDetected: If sleeping cell alarm was detected
        """
        for watchdog_dic in self.watchdogs:
            watchdog, bts_id, du_id = \
                watchdog_dic.get('watchdog', None), watchdog_dic.get('bts_id', 0), watchdog_dic.get('du_id', 0)
            if watchdog is None:
                raise WatchdogNotStarted(f'Watchdog not started for BTS #{bts_id}, DU #{du_id}')
            for detected_alarm in watchdog.get_detected_alarms():
                if self._is_sleeping_cell_alarm_detected(detected_alarm=detected_alarm):
                    logging.warning(f'Sleeping cell detected on BTS #{bts_id}, DU #{du_id}. '
                                    f'Snapshot will be collected.')
                    watchdog.stop_watching_alarms()
                    raise DisallowedAlarmsDetected(f'\n{detected_alarm}')
            logging.debug(f'Sleeping cell not detected on BTS #{bts_id}, DU #{du_id}')
            watchdog.stop_watching_alarms()

    def enable_sleeping_cell_detection_feature(self, bts_id: int = 0, du_id: int = 0) -> None:
        """
        Enable sleeping cell detection feature based on BTS cell types.
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        cell_types = self._get_and_parse_bts_info_to_turn_on_sleeping_cell()
        if 'nr' in cell_types:
            self.enable_sleeping_cell_detection_feature_for_5g(
                bts_id=bts_id,
                du_id=du_id
            )
        if 'lnbts_nr' in cell_types:
            pass
        if 'lte' in cell_types:
            self.enable_sleeping_cell_detection_feature_for_lte(
                bts_id=bts_id,
                du_id=du_id
            )
        if 'lnbts_lte' in cell_types:
            pass

    def enable_sleeping_cell_detection_feature_for_all_bts(self) -> None:
        """
        Enable sleeping cell detection feature for all BTS and DU units in testline.
        """
        self._iterate_over_bts_and_dus(self.enable_sleeping_cell_detection_feature)

    def start_sleeping_cell_detection_watchdog_for_all_bts(self, log_dir: Optional[str] = None) -> None:
        """
        Enable sleeping cell detection watchdog for all BTS and DU units in testline.
        :param log_dir (Optional[str]): Directory for storing logs and snapshots
        """
        self._iterate_over_bts_and_dus(self.start_sleeping_cell_detection_watchdog, log_dir=log_dir)

    def enable_sleeping_cell_detection_feature_for_5g(self, bts_id: int = 0, du_id: int = 0) -> None:
        """
        Enable sleeping cell detection feature for 5G cells by configuring FEATCADM parameters.
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        logging.info(f'Checking sleeping cell detection for 5G BTS: {bts_id}, DU: {du_id} and enabling if needed')
        if self._check_rach_based_sleeping_cell_detection_feature_enabled(technology_type='5G', bts_id=bts_id, du_id=du_id):
            logging.info(f'Sleeping cell detection for 5G is already enabled on BTS: {bts_id}, DU: {du_id}')
            return
        self._enable_rach_based_sleeping_cell_detection_5g(bts_id=bts_id, du_id=du_id)

    def enable_sleeping_cell_detection_feature_for_lte(self, bts_id: int = 0, du_id: int = 0) -> None:
        """
        Enable sleeping cell detection feature for LTE cells by configuring FEATCADM parameters.
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        logging.info(f'Checking sleeping cell detection for LTE BTS: {bts_id}, DU: {du_id} and enabling if needed')
        if self._check_rach_based_sleeping_cell_detection_feature_enabled(technology_type='LTE', bts_id=bts_id, du_id=du_id):
            logging.info(f'Sleeping cell detection for LTE is already enabled on BTS: {bts_id}, DU: {du_id}')
            return
        self._enable_rach_based_sleeping_cell_detection_lte(bts_id=bts_id, du_id=du_id)

    def _iterate_over_bts_and_dus(self, func: Callable, **kwargs: Any) -> None:
        """
        Iterate over all BTS and DU units in testline and execute given function.
        :param func (Callable): Function to execute for each BTS/DU pair
        :param kwargs (Any): Additional keyword arguments to pass to the function
        """
        for bts_id in range(len(self.tl.gnbs)):
            for du_id in range(len(self.tl.gnbs[int(bts_id)].dus)):
                func(bts_id=bts_id, du_id=du_id, **kwargs)

    def _is_sleeping_cell_alarm_detected(self, detected_alarm: Alarm) -> bool:
        """
        Check if the detected alarm matches sleeping cell alarm criteria.
        :param detected_alarm (Alarm): Alarm object to check
        :return (bool): True if alarm matches sleeping cell criteria, False otherwise
        """
        return all([detected_alarm.alarm_id == self.SLEEPING_CELL_ALARM_ID,
                    detected_alarm.fault_id == self.SLEEPING_CELL_FAULT_ID,
                    detected_alarm.fault_name == self.SLEEPING_CELL_FAULT_NAME])

    def _enable_rach_based_sleeping_cell_detection_5g(self, bts_id: int, du_id: int) -> None:
        """
        Enable RACH-based sleeping cell detection for 5G by configuring FEATCADM and SLCELLDRCONF parameters.
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        dist_names = [
            'MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
            'MRBTS-{}/MNL-1/MNLENT-1/TRBLCADM-1/SLCELLDRCONF-1'
        ]
        parameters = [
            {
                'parameterName': 'actAutRachBasedSlCellDetRec', 'operation': 'update', 'value': 'false'
            },
            {
                'parameterName': 'actNrAutCntRachStpSlCellDetRec', 'operation': 'update', 'value': 'true'
            },
            {
                'parameterName': 'nrCntRachStpSlCellDetHChFrq', 'operation': 'update', 'value': '300'
            },
            {
                'parameterName': 'nrCntRachStpSlCellDetMsg3Thr', 'operation': 'update', 'value': '0'
            },
            {
                'parameterName': 'nrCntRachStpSlCellRecPh1Tmr', 'operation': 'update', 'value': '900'
            },
            {
                'parameterName': 'autRachBasedSlCellRecPh1Timer', 'operation': 'update', 'value': '900'
            },
            {
                'parameterName': 'nrCntRachStpSlCellDetThr', 'operation': 'update', 'value': '1000'
            },
            {
                'parameterName': 'nrCntRachStpSlCellRecPhAct', 'operation': 'update', 'value': 'Phase 1'
            },
        ]

        try:
            logging.info(f'Enable sleeping cell detection for 5G BTS: {bts_id}, DU: {du_id}')
            operation_type = self._get_class_operation_type(class_name='FEATCADM', bts_id=bts_id, du_id=du_id)
            self.commissioning.perform_object_recommissioning(
                dist_name=dist_names[0], parameter=parameters[:2], operation=operation_type,
                skip_parameter_relation_errors=True, timeout=300, bts_id=bts_id, du_id=du_id
            )
            logging.info(f'Parameter(s) {parameters[:2]} in dist name {dist_names[0]} were updated')
            operation_type = self._get_class_operation_type(class_name='SLCELLDRCONF', bts_id=bts_id, du_id=du_id)
            self.commissioning.perform_object_recommissioning(
                dist_name=dist_names[1], parameter=parameters[2:], operation=operation_type,
                skip_parameter_relation_errors=True, timeout=300, bts_id=bts_id, du_id=du_id
            )
            logging.info(f'Parameter(s) {parameters[2:]} in dist name {dist_names[1]} were updated')
            logging.info(f'Sleeping cell detection for 5G enabled successfully for BTS: {bts_id}, DU: {du_id}')
        except AdminApiProcedureFailureException as err:
            logger.log_warn_to_console(
                msg=f"Error has occured during RACH sleeping cell feature activation for 5G: {str(err)}",
                log_hierarchy=1
            )
            logging.info(str(err))
            if 'Runtime plan has no modified objects!' not in str(err):
                raise

    def _enable_rach_based_sleeping_cell_detection_lte(self, bts_id: int, du_id: int) -> None:
        """
        Enable RACH-based sleeping cell detection for LTE by configuring FEATCADM and SLCELLDRCONF parameters.
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        """
        dist_names = [
            'MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1',
            'MRBTS-{}/MNL-1/MNLENT-1/TRBLCADM-1/SLCELLDRCONF-1'
        ]
        parameters = [
            {
                'parameterName': 'actAutRachBasedSlCellDetRec', 'operation': 'update', 'value': 'true'
            },
            {
                'parameterName': 'autRachBasedSlCellDetHCheckFreq', 'operation': 'update', 'value': '300'
            },
            {
                'parameterName': 'autRachBasedSlCellRachAtmpThr', 'operation': 'update', 'value': '1000'
            },
            {
                'parameterName': 'autRachBasedSlCellRachMsg3Thr', 'operation': 'update', 'value': '0'
            },
            {
                'parameterName': 'autRachBasedSlCellRecPh1Timer', 'operation': 'update', 'value': '900'
            },
            {
                'parameterName': 'autRachBasedSlCellRecPhaseAct', 'operation': 'update', 'value': 'Phase 1'
            },
        ]
        try:
            logging.info(f'Enable sleeping cell detection for LTE BTS: {bts_id}, DU: {du_id}')
            operation_type = self._get_class_operation_type(class_name='FEATCADM', bts_id=bts_id, du_id=du_id)
            self.commissioning.perform_object_recommissioning(
                dist_name=dist_names[0], parameter=parameters[:1],
                operation=operation_type, skip_parameter_relation_errors=True,
                timeout=300, bts_id=bts_id, du_id=du_id
            )
            logging.info(f'Parameter(s) {parameters[:1]} in dist name {dist_names[0]} was updated')
            operation_type = self._get_class_operation_type(class_name='SLCELLDRCONF', bts_id=bts_id, du_id=du_id)
            self.commissioning.perform_object_recommissioning(
                dist_name=dist_names[1], parameter=parameters[1:], operation=operation_type,
                skip_parameter_relation_errors=True, timeout=300, bts_id=bts_id, du_id=du_id
            )
            logging.info(f'Parameter(s) {parameters[1:]} in dist name {dist_names[1]} was updated')
            logging.info(f'Sleeping cell detection for LTE enabled successfully for BTS: {bts_id}, DU: {du_id}')
        except AdminApiProcedureFailureException as err:
            logger.log_warn_to_console(
                msg=f"Error has occured during RACH sleeping cell feature activation for LTE: {str(err)}",
                log_hierarchy=1
            )
            logging.info(str(err))
            if 'Runtime plan has no modified objects!' not in str(err):
                raise

    def _check_rach_based_sleeping_cell_detection_feature_enabled(self, technology_type: str,
                                                                  bts_id: int = 0, du_id: int = 0) -> bool:
        """
        Check if RACH-based sleeping cell detection feature is enabled for specified technology.
        For 5G checks 'actNrAutCntRachStpSlCellDetRec', for LTE checks 'actAutRachBasedSlCellDetRec'.
        :param technology_type (str): Technology type ('5G' or 'LTE')
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        :return (bool): True if enabled, False otherwise
        """
        if technology_type == '5G':
            sc_validation_param = 'actNrAutCntRachStpSlCellDetRec'
        else:
            sc_validation_param = 'actAutRachBasedSlCellDetRec'
        result = self.commissioning.get_parameters_by_class(
            class_name="FEATCADM",
            parameter_list=[sc_validation_param],
            bts_id=bts_id,
            du_id=du_id
        )

        try:
            sleeping_cell_parameter_value = result[0]['parameters'].get(sc_validation_param, False)
        except (IndexError, KeyError):
            logger.log_warn_to_console(
                msg=f'Parameter {sc_validation_param} not found in FEATCADM class. Returning False.',
                log_hierarchy=1
            )
            sleeping_cell_parameter_value = False
        return sleeping_cell_parameter_value

    def _get_and_parse_bts_info_to_turn_on_sleeping_cell(self) -> List[str]:
        """
        Get BTS information and parse cell types to determine which sleeping cell detection to enable.
        :return (List[str]): List of cell types present in BTS (e.g., 'nr', 'lte', 'lnbts_nr', 'lnbts_lte')
        """
        cell_type_in_bts = []
        bts_info = self.du.get_bts_info()
        if bts_info['cells']['lte']:
            if 'LNBTS' in str(bts_info['cells']['lte']):
                cell_type_in_bts.append('lnbts_lte')
            else:
                cell_type_in_bts.append('lte')
        if bts_info['cells']['nr']:
            if 'LNBTS' in str(bts_info['cells']['nr']):
                cell_type_in_bts.append('lnbts_nr')
            else:
                cell_type_in_bts.append('nr')
        return cell_type_in_bts

    def _get_class_operation_type(self, class_name: str, bts_id: int = 0, du_id: int = 0) -> str:
        """
        Determine operation type for class commissioning based on class existence in BTS configuration.
        :param class_name (str): Name of the class to check
        :param bts_id (int): BTS id
        :param du_id (int): DU id
        :return (str): 'update' if class exists, 'create' otherwise
        """
        result = self.commissioning.get_parameters_by_class(
            class_name=class_name,
            parameter_list=None,
            bts_id=bts_id,
            du_id=du_id
        )
        return 'update' if bool(result) else 'create'
